        var mod = loadPreCliDevelopmentSetup({
            loadProjectConfig: function () { return makeConfig(); },
            paramsForConfigLoad: function (p) { return p; }
        }, {});
        mod.postSetupErrorComment({}, {}, 'PROJ-12', 'Git Branch Setup', 'boom');
    });

});
