{
  "key": "gh-770",
  "fields": {
    "summary": "[ENH] Tracker-agnostic agent scripts: rework/dev legs emit Jira JQL + wiki markup against GitHub tracker (owner: use tracker_* aliases)",
    "description": "Owner observation 2026-10-06 (live rework leg log, gh-1308 on flutter_agent_harness):

```
Calling tool jira_search_by_jql {"jql":"parent = gh-1308 AND issuetype = Subtask ..."}
tracker: jira_search_by_jql → github issues   ← routes, but JQL is Jira-speak → returns empty
Failed to fetch questions, continuing without file: {}
Calling tool jira_post_comment {"key":"gh-1308","comment":"h3. 🔧 Automated Rework Started ... {panel:...} ... {code}ai/gh-1308{code} ..."}
tracker: gh-1308 → github issues   ← posts Jira wiki markup as literal text on GitHub
```

Two breakages on a GitHub-backed tracker:
1. **Query layer:** scripts send JQL (`parent = gh-1308 AND issuetype = Subtask`) — meaningless on GitHub, silently returns empty.
2. **Rendering layer:** comments carry Jira wiki markup (`h3.`, `{panel:bgColor=...}`, `{code}...`) — renders as raw text garbage in GitHub issues.

Owner expectation: agent scripts must go through the tracker abstraction (tracker_* family / js/common/trackers.js — the scm.js analog, branch feat/tracker-agnostic-helpers @ d9fc8fc, NOT yet merged) instead of hard-coded jira_* calls, and render markup per-tracker (Markdown on GitHub, wiki on Jira). Related: jiraHelpers-bound actions (validateTicketKeyFormat etc.) are the known anchor points."
  }
}

/**
 * Tracker-agnostic ticket helpers — the scm.js analog for trackers.
 *
 * Maps generic ticket operations onto CANONICAL tracker tools per
 * configured provider — jira_* (default), ado_*, github_* — exactly like
 * scm.js maps SCM operations onto providers.
 *
 * Why canonical tools and not the tracker_* family: on the Java runtime
 * tracker_* exists solely as a CLI alias (resolved via DEFAULT_TRACKER in
 * McpCliHandler); the JS surface exposes canonical names only. Provider
 * mapping therefore lives in this layer, in JS.
 *
 * Factory: createTracker(config, customParams)
 *   Provider probing order (first non-empty, valid value wins):
 *     1. customParams.trackerProvider   — per-agent override, e.g.
 *        { "customParams": { "trackerProvider": "ado" } }
 *     2. config.tracker.provider        — project config, 'jira' | 'ado' | 'github'
 *     3. DEFAULT_TRACKER env var        — the deployment-level signal; it
 *        reflects which tracker integration is actually active in the Java
 *        runtime (jira_* / ado_* / github_* tools). This is what lets the
 *        same script run unchanged on GitHub-tracker deployments whose
 *        project config never mentions a tracker.
 *     4. config.defaultTracker          — configLoader-consistent fallback
 *     5. 'jira'                         — default
 *   config.repository: { owner, repo }  // GitHub issue key expansion
 *   config.labels: { aiGenerated }      // overrides LABELS.AI_GENERATED
 *
 * Per-agent override via JSON customParams:
 *   { "customParams": { "trackerProvider": "ado" } }
 *
 * Provider capabilities: jira supports every operation; ado covers
 * tickets/search/comments/status/assign/create (labels are not exposed by
 * the ado toolset); github covers everything — search/assignTo/moveToStatus
 * prefer the dedicated issue tools (github_search_issues, github_assign_issue,
 * github_move_issue_to_status) when the runtime exposes them (Java runtime),
 * with graceful degradation where it does not (Dart catalog): moveToStatus
 * falls back to close-on-done + status-as-label over the basic issue tools,
 * while search/assignTo throw a clear error.
 */

const { STATUSES, LABELS } = require('../config.js');

/**
 * Parse a tool result that may arrive as an object or a JSON string.
 * Non-JSON strings pass through untouched (scm.js convention).
 */
function _parseJson(raw) {
    if (typeof raw === 'string') {
        try { return JSON.parse(raw); } catch (e) { return raw; }
    }
    return raw;
}

/**
 * Normalize a collection of label entries into plain names.
 * Jira/ADO give strings; GitHub gives [{ name: '...' }].
 */
function _labelNames(raw) {
    var parsed = _parseJson(raw);
    if (!Array.isArray(parsed)) return [];
    var names = [];
    for (var i = 0; i < parsed.length; i++) {
        var entry = parsed[i];
        if (typeof entry === 'string') {
            names.push(entry);
        } else if (entry && typeof entry.name === 'string') {
            names.push(entry.name);
        }
    }
    return names;
}

/**
 * Normalize one comment into { author, body, created }.
 * Candidates cover Jira, GitHub, and ADO field namings; unknown shapes
 * keep their raw body field when present.
 */
function _normalizeComment(raw) {
    var c = _parseJson(raw);
    if (!c || typeof c !== 'object') return null;
    var author = '';
    var authorCandidates = [c.author, c.user, c.createdBy];
    for (var i = 0; i < authorCandidates.length; i++) {
        var a = authorCandidates[i];
        if (!a) continue;
        if (typeof a === 'string') { author = a; break; }
        if (a.displayName || a.login || a.uniqueName) {
            author = a.displayName || a.login || a.uniqueName;
            break;
        }
    }
    return {
        author: author,
        body: c.body || c.text || '',
        created: c.created || c.created_at || c.createdDate || null
    };
}

/**
 * Read a ticket assignee out of backend-specific shapes.
 */
function _assigneeName(fields) {
    var candidates = [
        fields.assignee, fields.assignments,
        fields['System.AssignedTo']
    ];
    for (var i = 0; i < candidates.length; i++) {
        var a = candidates[i];
        if (!a) continue;
        if (typeof a === 'string') return a;
        if (a.displayName || a.login || a.uniqueName || a.accountId) {
            return a.displayName || a.login || a.uniqueName || a.accountId;
        }
    }
    return null;
}

/**
 * Read the DEFAULT_TRACKER env var when running under GraalJS (Java host
 * access); null everywhere else (plain JS test harnesses) or when unset.
 */
function _defaultTrackerEnv() {
    try {
        var v = java.lang.System.getenv('DEFAULT_TRACKER');
        return v ? String(v).trim() : null;
    } catch (e) {
        return null;
    }
}

function createTracker(config, customParams) {
    var VALID = ['jira', 'ado', 'github'];
    var raw =
        (customParams && customParams.trackerProvider) ||
        (config && config.tracker && config.tracker.provider) ||
        _defaultTrackerEnv() ||
        (config && config.defaultTracker) ||
        '';
    var providerName = VALID.indexOf(String(raw).toLowerCase()) !== -1
        ? String(raw).toLowerCase()
        : 'jira';
    var owner = (config && config.repository && config.repository.owner) || '';
    var repo  = (config && config.repository && config.repository.repo)  || '';
    var aiLabel = (config && config.labels && config.labels.aiGenerated)
        || LABELS.AI_GENERATED;

    function provider() {
        return providerName;
    }

    function unsupported(op) {
        throw new Error(
            'trackers: operation "' + op + '" is not supported by the ' +
            providerName + ' provider'
        );
    }

    /**
     * Expand a bare numeric issue number into "owner/repo#N" (GitHub
     * keys) when the repository is configured. Other keys pass through.
     */
    function expandKey(key) {
        var k = String(key == null ? '' : key).trim();
        if (/^\d+$/.test(k) && owner && repo) {
            return owner + '/' + repo + '#' + k;
        }
        return k;
    }

    function githubIssueNumber(key) {
        var k = expandKey(key);
        var m = /^[\w.-]+\/[\w.-]+#(\d+)$/.exec(k) || /^(\d+)$/.exec(k);
        if (!m) {
            throw new Error('trackers: cannot parse GitHub issue key: ' + key);
        }
        return parseInt(m[1], 10);
    }

    /**
     * Build the argument bag for the dedicated GitHub issue tools
     * (github_assign_issue / github_move_issue_to_status). Carries BOTH the
     * composite key and the explicit owner/repo/number parts so the call
     * works against runtimes whose tool schema accepts only one of the two
     * shapes: the Java tools resolve either (explicit parts win over key),
     * the Dart issue family speaks owner/repo/number. For composite keys the
     * parts are parsed FROM THE KEY (the key is authoritative); for bare
     * numbers the configured repository fills in.
     */
    function githubIssueArgs(key) {
        var k = expandKey(key);
        var m = /^([\w.-]+)\/([\w.-]+)#(\d+)$/.exec(k);
        if (m) {
            return { key: k, owner: m[1], repo: m[2], number: parseInt(m[3], 10) };
        }
        var args = { key: k, number: githubIssueNumber(k) };
        if (owner) args.owner = owner;
        if (repo) args.repo = repo;
        return args;
    }

    // ── jira provider (canonical jira_* tools) ────────────────────────────

    function jiraGetTicket(key) {
        return normalizeTicket(jira_get_ticket({ key: key }));
    }

    function jiraSearch(query) {
        return _ticketPage(jira_search_by_jql({ jql: query }), 'issues');
    }

    function jiraPostComment(key, comment) {
        return jira_post_comment({ key: key, comment: comment });
    }

    function jiraGetComments(key) {
        return _commentPage(jira_get_comments({ key: key }), 'comments');
    }

    function jiraMoveToStatus(key, status) {
        return jira_move_to_status({ key: key, statusName: status });
    }

    function jiraAssignTo(key, user) {
        return jira_assign_ticket_to({ key: key, accountId: user });
    }
…

/**
 * Tracker-aware comment markup helpers.
 *
 * Post-action templates historically hard-code Jira wiki markup
 * (`h3.`, `{code}`, `*bold*`, `[text|url]`). When the ticket lives on
 * GitHub Issues (key shapes `gh-12`, `owner/repo#12`, `#12`, bare `12`)
 * those comments render as noise. These helpers render each construct in
 * the flavor of the ticket's tracker: Jira wiki for Jira keys, Markdown
 * for GitHub keys — with an explicit override via
 * `customParams.commentMarkup` (`'jira' | 'markdown'`, `'github'` is
 * accepted as an alias for `'markdown'`).
 *
 * Usage:
 *   var commentMarkup = require('./common/commentMarkup.js');
 *   var m = commentMarkup.forTicket(ticketKey, customParams);
 *   var comment = m.h(3, 'Development Completed') + '\n\n' +
 *       m.bold('Branch:') + ' ' + m.code(branchName) + '\n';
 *
 * The Jira flavor output is byte-identical to the historical templates,
 * so Jira-facing behavior is unchanged.
 */
'use strict';

var GITHUB_KEY_SHAPES = [
    /^gh-\d+$/i,               // gh-122 — GitHub router key convention
    /^[\w.-]+\/[\w.-]+#\d+$/,  // epam/dmtools-dart#122
    /^#\d+$/,                  // #122
    /^\d+$/                    // 122
];

function flavorForTicket(ticketKey, customParams) {
    var explicit = customParams && customParams.commentMarkup;
    if (typeof explicit === 'string' && explicit) {
        var norm = explicit.toLowerCase();
        if (norm === 'markdown' || norm === 'github') return 'markdown';
        if (norm === 'jira') return 'jira';
    }
    var key = String(ticketKey == null ? '' : ticketKey).trim();
    for (var i = 0; i < GITHUB_KEY_SHAPES.length; i++) {
        if (GITHUB_KEY_SHAPES[i].test(key)) return 'markdown';
    }
    return 'jira';
}

function markdownFlavor() {
    return {
        h: function (level, text) {
            var prefix = '';
            for (var i = 0; i < level; i++) prefix += '#';
            return prefix + ' ' + text;
        },
        bold: function (text) { return '**' + text + '**'; },
        italic: function (text) { return '_' + text + '_'; },
        code: function (text, lang) {
            return '```' + (lang || '') + '\n' + text + '\n```';
        },
        link: function (text, url) { return '[' + text + '](' + url + ')'; },
        panel: function (title, body, jiraOpts) {
            var header = title ? '> **' + title + '**\n>\n' : '';
            var quoted = String(body).split('\n').map(function (line) {
                return '> ' + line;
            }).join('\n');
            return header + quoted;
        }
    };
}

function jiraFlavor() {
    return {
        h: function (level, text) { return 'h' + level + '. ' + text; },
        bold: function (text) { return '*' + text + '*'; },
        italic: function (text) { return '_' + text + '_'; },
        code: function (text, lang) {
            return '{code' + (lang ? ':' + lang : '') + '}' + text + '{code}';
        },
        link: function (text, url) { return '[' + text + '|' + url + ']'; },
        panel: function (title, body, jiraOpts) {
            var open = '{panel' +
                (title ? ':title=' + title : '') +
                (jiraOpts ? (title ? '|' : ':') + jiraOpts : '') +
                '}';
            return open + body + '\n{panel}';
        }
    };
}

function forFlavor(flavor) {
    return flavor === 'markdown' ? markdownFlavor() : jiraFlavor();
}

function forTicket(ticketKey, customParams) {
    return forFlavor(flavorForTicket(ticketKey, customParams));
}

module.exports = {
    flavorForTicket: flavorForTicket,
    forFlavor: forFlavor,
    forTicket: forTicket
};

/**
 * Pre-CLI Rework Setup Action (preCliJSAction for pr_rework agent)
 * 1. Finds the existing PR for the ticket
 * 2. Checks out the PR branch
 * 3. Merges origin/{baseBranch} into the PR branch (auto-update, before setup commands run —
 *    see the comment above the detectMergeConflicts() call for why the order matters)
 * 4. Runs project-specific setup commands (build/verify) against the now-updated branch
 * 5. Writes input folder: pr_info.md, pr_diff.txt, pr_discussions.md, pr_discussions_raw.json
 * 6. Fetches question subtasks with answers (extra context)
 * 7. Posts "Rework Started" comment to the ticket (Jira/ADO/GitHub via common/trackers.js)
 */

var configLoader = require('./configLoader.js');
var trackersModule = require('./common/trackers.js');
const gh = require('./common/githubHelpers.js');
const gitOps = require('./common/gitOps.js');
const { resolveStatuses } = require('./config.js');
const fetchQuestionsToInput = require('./fetchQuestionsToInput.js');
const fetchParentContextToInput = require('./fetchParentContextToInput.js');
var restoreFromReleases = require('./restoreFromReleases.js');
var setupCommands = require('./common/setupCommands.js');
var baseBranchMarker = require('./common/baseBranchMarker.js');

/**
 * Optionally syncs the PR's base branch with its own upstream (config.git.baseBranch)
 * before merge-conflict detection runs. Relevant in two-branch mode, where the PR's base is
 * a long-lived branch (e.g. "release/rc_*") that can drift stale relative to
 * config.git.baseBranch over time. Delegates to a project-specific hook
 * (customParams.branchSyncFnPath) because syncing may require bypassing branch-protection
 * rules that block direct pushes to that branch — same rationale as
 * customParams.branchCreateFnPath in checkoutBranch.js.
 *
 * No-op when branchSyncFnPath isn't configured, or when the PR's base already IS
 * config.git.baseBranch (nothing to sync). Failures are logged and swallowed — the sync is
 * a best-effort freshness step, not a hard prerequisite for the rest of the rework flow.
 *
 * @param {string} baseBranch    - the PR's base branch (prDetails.base.ref)
 * @param {Object} customParams  - agent customParams (may contain branchSyncFnPath)
 * @param {Object} config        - resolved project config (config.git.baseBranch, workingDir)
 */
function syncBaseBranchIfConfigured(baseBranch, customParams, config) {
    if (!customParams || !customParams.branchSyncFnPath || !baseBranch || baseBranch === config.git.baseBranch) {
        return;
    }
    var branchSyncFn = configLoader.loadHookFn(customParams.branchSyncFnPath, 'branchSyncFnPath');
    if (!branchSyncFn) {
        return;
    }
    try {
        console.log('Syncing base branch', baseBranch, 'via', customParams.branchSyncFnPath);
        branchSyncFn({
            branchName: baseBranch,
            targetBranch: config.git.baseBranch,
            workingDir: config.workingDir,
            config: config
        });
        cli_execute_command({ command: gh.buildOriginFetchCommand() });
    } catch (e) {
        console.warn('branchSyncFnPath failed (non-fatal):', e && e.toString ? e.toString() : String(e));
    }
