```js
function githubIssueNumber(key) {
    var k = expandKey(key);
    var m = /^[\w.-]+\/[\w.-]+#(\d+)$/.exec(k) || /^(\d+)$/.exec(k);
    if (!m) {
        throw new Error('trackers: cannot parse GitHub issue key: ' + key);
    }
    return parseInt(m[1], 10);
