// GitHub issue key shapes (gh-770) — same convention as commentMarkup's
// GITHUB_KEY_SHAPES: the machine loop keys issues 'gh-N', the Dart runtime
// uses 'owner/repo#N', and bare numbers appear in dispatch payloads.
var GITHUB_KEY_SHAPES = [
    /^gh-\d+$/i,
    /^[\w.-]+\/[\w.-]+#\d+$/,
    /^#\d+$/,
    /^\d+$/
];

function isGitHubKeyShape(key) {
    var k = String(key == null ? '' : key).trim();
    for (var i = 0; i < GITHUB_KEY_SHAPES.length; i++) {
        if (GITHUB_KEY_SHAPES[i].test(k)) return true;
    }
    return false;
}

function extractTicketKeyFromJql(jql) {
    if (!jql || typeof jql !== 'string') return null;
    // gh-N router keys and composite GitHub keys are matched BEFORE the Jira
    // shape so they keep their original case (uppercasing would mint 'GH-12',
    // a different key from the 'gh-12' the machine loop created).
    var m = jql.match(/key\s*(?:=|in\s*\()\s*(gh-\d+|[\w.-]+\/[\w.-]+#\d+|#\d+|\d+)/i);
    if (m && m[1]) return m[1];
    m = jql.match(/key\s*(?:=|in\s*\()\s*([A-Z][A-Z0-9_]*-\d+)/i);
    return m ? m[1].toUpperCase() : null;
}
